const API_BASEURL = "http://127.0.0.1:8000/api";

const API_ENDPOINTS = {
    text: `${API_BASEURL}/text`,
    image: `${API_BASEURL}/images`,
    button: `${API_BASEURL}/button`,
    addon: `${API_BASEURL}/addon`
};

export {API_BASEURL, API_ENDPOINTS};
